preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtweb-font-size로 바꿉니다. */
.rtweb {
  --rtweb-bg-fill: transparent;
  --rtweb-bg-border: 0;
  --rtweb-blur: none;
  --rtweb-bg-edge: none;
  --rtweb-bg-sheen: linear-gradient(transparent, transparent);
  --rtweb-bg-fallback: transparent;
  --rtweb-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtweb-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtweb-font-size: 16.5px;
  --rtweb-line-height: 1.95;
  --rtweb-para-gap: 1.5em;
  --rtweb-measure: 38em;
  --rtweb-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtweb {
  --risu-font-family: var(--rtweb-font-body);
  --FontColorStandard: var(--rtweb-ink);
  --FontColorBold: var(--rtweb-strong, var(--rtweb-ink));
  --FontColorItalic: var(--rtweb-muted);
  --FontColorItalicBold: var(--rtweb-muted);
  --FontColorQuote1: var(--rtweb-muted);
  --FontColorQuote2: var(--rtweb-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtweb-ink);
  font-family: var(--rtweb-font-body);
  font-size: var(--rtweb-font-size);
  line-height: var(--rtweb-line-height);
  letter-spacing: var(--rtweb-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtweb, .rtweb *, .rtweb *::before, .rtweb *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtweb.rtweb { display: block; }
.rtweb ::selection { background: color-mix(in srgb, var(--rtweb-accent) 26%, transparent); color: inherit; }
.rtweb__content {
  min-width: 0;
  color: var(--rtweb-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtweb__content .chattext {
  --tw-prose-code: var(--rtweb-strong, var(--rtweb-ink));
  --tw-prose-pre-code: var(--rtweb-ink);
  --tw-prose-pre-bg: var(--rtweb-tint);
  max-width: none;
  color: var(--rtweb-ink);
  font-size: var(--rtweb-font-size) !important;
  line-height: var(--rtweb-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtweb__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtweb-font-size);
  line-height: var(--rtweb-line-height);
}
.rtweb__content :where(p) { margin: 0 0 var(--rtweb-para-gap); }
.rtweb__content :where(p:last-child) { margin-bottom: 0; }
.rtweb__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtweb-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtweb-strong, var(--rtweb-ink));
  font-family: var(--rtweb-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtweb__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtweb__content :where(h1) { font-size: calc(var(--rtweb-font-size) * 1.55); }
.rtweb__content :where(h2) { font-size: calc(var(--rtweb-font-size) * 1.32); }
.rtweb__content :where(h3) { font-size: calc(var(--rtweb-font-size) * 1.15); }
.rtweb__content :where(h4, h5, h6) { font-size: var(--rtweb-font-size); color: var(--rtweb-muted); }
.rtweb__content :where(strong) { font-weight: 700; color: var(--rtweb-strong, var(--rtweb-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtweb__content :where(em) { font-style: normal; color: var(--rtweb-muted); }
.rtweb__content mark[risu-mark="quote1"],
.rtweb__content mark[risu-mark="blockquote1"] { color: var(--rtweb-muted); background: transparent; }
.rtweb__content mark[risu-mark="quote2"],
.rtweb__content mark[risu-mark="blockquote2"] {
  color: var(--rtweb-dialog);
  font-weight: var(--rtweb-dialog-weight);
  background: transparent;
}
.rtweb__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtweb-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtweb-tint);
  color: var(--rtweb-muted);
}
.rtweb__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtweb__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtweb-ink); }
.rtweb__content :where(li)::marker { color: var(--rtweb-accent); }
.rtweb__content :where(a) {
  color: var(--rtweb-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtweb-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtweb__content :where(a:hover) { text-decoration-color: currentColor; }
.rtweb__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtweb-line) 15%, var(--rtweb-line) 85%, transparent);
}
.rtweb__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtweb-strong, var(--rtweb-ink));
  background: var(--rtweb-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtweb-font-size) * .88);
  line-height: 1.5;
}
.rtweb__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtweb-ink);
  background: var(--rtweb-tint);
  border: 1px solid var(--rtweb-line);
  border-radius: .5rem;
  font-size: calc(var(--rtweb-font-size) * .88);
  line-height: 1.55;
}
.rtweb__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtweb__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtweb__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtweb-ink);
  border-bottom: 1px solid var(--rtweb-line);
  text-align: left;
  vertical-align: top;
}
.rtweb__content :where(th) {
  background: var(--rtweb-tint);
  color: var(--rtweb-strong, var(--rtweb-ink));
  font-weight: 600;
}
.rtweb__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtweb__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtweb-ink) !important;
  background: var(--rtweb-edit-bg) !important;
  border: 1px solid var(--rtweb-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtweb-font-size) !important;
  line-height: var(--rtweb-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtweb__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtweb-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtweb-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtweb__footer {
  --risu-theme-textcolor2: var(--rtweb-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtweb-muted);
}
.rtweb__info, .rtweb__actions { min-width: 0; max-width: 100%; }
.rtweb__info > div, .rtweb__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; }
.rtweb__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtweb__info button.transition-all,
.rtweb__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtweb__info button.transition-all:hover,
.rtweb__actions button[class*="button-icon-"]:hover { background: var(--rtweb-tint); color: var(--rtweb-ink); }
.rtweb__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtweb-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtweb__info button:not(.transition-all):hover { background: var(--rtweb-tint); color: var(--rtweb-ink); }
.rtweb :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtweb-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtweb__portrait { overflow: hidden; background: var(--rtweb-tint); }
.rtweb__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtweb, .rtweb * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtweb .rtweb__bg {
    background: var(--rtweb-bg-fallback, var(--rtweb-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtweb .rtweb__bg { background: var(--rtweb-bg-fallback, var(--rtweb-bg-fill)); }
}

.rtweb__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtweb-bg-fill);
  border: var(--rtweb-bg-border, 0);
  -webkit-backdrop-filter: var(--rtweb-blur);
  backdrop-filter: var(--rtweb-blur);
  box-shadow: var(--rtweb-bg-edge);
}

/* 구조: 웹소설 */

.rtweb {
  background: var(--rtweb-outer);
  padding: var(--rtweb-wrap-y, 0px) clamp(1rem, 4vw, 2.5rem);
}
.rtweb__page {
  position: relative;
  max-width: var(--rtweb-measure);
  margin: 0 auto;
  padding: 1.65rem var(--rtweb-page-px, 0px) 1.15rem;
  border-radius: var(--rtweb-page-r, 0px);
}
.rtweb .rtweb__bg { background: var(--rtweb-bg-sheen), var(--rtweb-paper); }
.rtweb__head {
  display: flex;
  align-items: center;
  gap: .65rem;
  margin-bottom: 1.15rem;
  color: var(--rtweb-accent);
  font-size: .8em;
  font-weight: 700;
  letter-spacing: .04em;
}
.rtweb__head::before {
  content: "";
  width: .42rem;
  height: .42rem;
  border-radius: 50%;
  background: var(--rtweb-accent);
  flex: none;
}
.rtweb__head::after {
  content: "";
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, var(--rtweb-line), transparent);
}
.rtweb--user .rtweb__page {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: .55rem var(--rtweb-page-px, 0px) .95rem;
}
.rtweb--user .rtweb__head { display: none; }
.rtweb--user .rtweb__content {
  max-width: min(86%, 30em);
  padding: .68em 1.05em;
  border: 1px solid var(--rtweb-line);
  border-left: 3px solid var(--rtweb-accent);
  border-radius: .55em;
  background: var(--rtweb-tint);
  box-shadow: 0 3px 12px var(--rtweb-shadow, rgba(0, 0, 0, .06));
}
.rtweb--user .rtweb__content .chattext,
.rtweb--user .rtweb__content :where(p, li) { font-size: calc(var(--rtweb-font-size) * .92) !important; line-height: 1.65 !important; }
.rtweb--user .rtweb__content :where(p) { margin-bottom: .4em; }
.rtweb__footer { margin-top: .6rem; }

.rtweb__footer { opacity: 0; transition: opacity .2s ease; }
.rtweb:hover .rtweb__footer, .rtweb:focus-within .rtweb__footer, .rtweb:has(textarea.message-edit-area) .rtweb__footer { opacity: 1; }
@media (hover: none) { .rtweb__footer { opacity: .68; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (글래스) ── */
.rtweb {
  --rtweb-blur: blur(16px) saturate(1.3);
  --rtweb-bg-sheen: radial-gradient(120% 80% at 0% 0%, rgba(255, 255, 255, .13), transparent 54%), linear-gradient(165deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .015) 68%);
  --rtweb-bg-edge: 0 14px 36px -14px rgba(0, 0, 0, .52), inset 0 1px 0 rgba(255, 255, 255, .24), inset 0 0 0 1px rgba(255, 255, 255, .13);
  --rtweb-bg-fallback: rgba(16, 18, 26, .88);
  --rtweb-outer: transparent;
  --rtweb-paper: rgba(14, 15, 20, .42);
  --rtweb-ink: #ebeae6;
  --rtweb-strong: #ffffff;
  --rtweb-muted: rgba(228, 227, 222, .68);
  --rtweb-accent: #d8cbb4;
  --rtweb-dialog: #ffffff;
  --rtweb-line: rgba(255, 255, 255, .15);
  --rtweb-tint: rgba(255, 255, 255, .07);
  --rtweb-edit-bg: rgba(10, 11, 15, .52);
  --rtweb-shadow: rgba(0, 0, 0, .26);
  --rtweb-wrap-y: .45rem;
  --rtweb-page-r: 1rem;
  --rtweb-page-px: clamp(1.15rem, 3.2vw, 2.1rem);
}
